INSERT INTO Plantilla_Rutina (id_plantilla, nombre, objetivo, nivel, dias_semana, duracion_estimada_min, observaciones, activo) VALUES
(1, 'Iniciación y Acondicionamiento (3 Días)', 'Iniciación / Acondicionamiento Físico General', 'Principiante', 3, 50, 'Rutina full-body de 3 días para adaptación anatómica y técnica. Calentamiento previo de 8-10 min y vuelta a la calma de 5 min. Cargas moderadas (RPE 6-7).', TRUE),
(2, 'Pérdida de Peso y Tonificación (3 Días)', 'Pérdida de Peso / Tonificación', 'Principiante / Intermedio', 3, 45, 'Rutina dinámica de alta densidad metabólica para optimizar gasto calórico. Respetar descansos cortos de 45 a 60 segundos.', TRUE),
(3, 'Musculación e Hipertrofia (4 Días)', 'Hipertrofia Muscular', 'Intermedio', 4, 55, 'Distribución torso/pierna para sobrecarga progresiva y volumen efectivo. Descansos controlados de 90 segundos.', TRUE),
(4, 'Fuerza y Halterofilia (3 Días)', 'Fuerza / Halterofilia', 'Avanzado', 3, 60, 'Enfoque en levantamientos básicos pesados multiarticulares. Descansos completos de 2 minutos para reposición energética.', TRUE);
