INSERT INTO Noticia (id_noticia, titulo, contenido, categoria, imagen_url, permanente, fecha_publicacion, id_usuario_autor) VALUES
(1, 'Reglamento de Convivencia y Uso de Instalaciones SOMA', 'Recordamos a todos los socios que es obligatorio el uso de toalla personal, la descarga de barras y mancuernas luego de cada serie y mantener el apto médico al día.', 'Institucional', NULL, TRUE, '2026-08-14', 1),
(2, 'Horarios de Atención y Feriados 2026', 'Lunes a Viernes de 07:00 a 22:00 hs. Sábados de 09:00 a 18:00 hs. Los días feriados nacionales el gimnasio permanece abierto en horario especial de 10:00 a 16:00 hs.', 'Horarios', NULL, TRUE, '2026-08-29', 1),
(3, 'Nuevas Plataformas de Peso Muerto y Racks Olímpicos', 'Ya se encuentran habilitadas en el sector de Peso Libre las 3 nuevas plataformas amortiguadas y barras olímpicas calibradas para entrenamientos de fuerza.', 'Equipamiento', NULL, FALSE, '2026-11-07', 3),
